const item = $input.first().json;
const regiao = item.regiao_interesse || 'Contorno & Firmeza';
const periodo = item.melhor_periodo || 'Manhã';

// Tabela de Ticket Medio Estimado por Protocolo (R$)
const tabelaValores = {
  'Terço Superior': 3200,
  'Terco Superior': 3200,
  'Terço Médio': 4800,
  'Terco Medio': 4800,
  'Contorno & Firmeza': 5400,
  'Qualidade da Pele': 3600
};

const valorEstimado = tabelaValores[regiao] || 4500;

// Calculo de Lead Scoring (Nota de Qualidade do Lead de 0 a 100)
let pontuacaoLead = 60;
if (valorEstimado >= 4800) pontuacaoLead += 25;
if (item.whatsapp && item.whatsapp.length >= 10) pontuacaoLead += 15;

const categoriaQualidade = pontuacaoLead >= 85
  ? 'LEAD DIAMANTE VIP (Score ' + pontuacaoLead + '/100)'
  : 'LEAD OURO QUALIFICADO (Score ' + pontuacaoLead + '/100)';

return [{
  json: {
    ...item,
    valor_estimado_reais: valorEstimado,
    score_qualidade_lead: pontuacaoLead,
    classificacao_crm: categoriaQualidade,
    canal_origem: item.utm_source || 'Landing Page Interativa LUMINA',
    data_hora_entrada: new Date().toLocaleString('pt-BR')
  }
}];

